for (size_t i = 0; i < polygon_coords.size(); ++i) {
    const std::vector<double>& coord = polygon_coords[i];
    double x = coord[0];
    double y = coord[1];
    Kernel::Point_3 pt(x, y, 0.0);
    Triangulation::Vertex_handle vh = triangulation.insert(pt);
    vhandles.push_back(vh);
}
if (!vhandles.empty()) {
    walk_start = vhandles[0];
}
for (size_t i = 0; i < vhandles.size(); ++i) {
    Triangulation::Vertex_handle a = vhandles[i];
    Triangulation::Vertex_handle b = vhandles[(i + 1) % vhandles.size()];
    triangulation.odd_even_insert_constraint(a, b);
}

